<template><label class="relative block"><span class="sr-only">{{ label }}</span><Icon name="search" class-name="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-adm-ink-muted"/><input :value="draft" type="search" :placeholder="placeholder" class="min-h-11 w-full rounded-md border border-adm-line bg-adm-surface px-3 pl-9 text-sm text-adm-ink placeholder:text-adm-ink-muted focus:border-adm-focus focus:outline-none focus:ring-2 focus:ring-adm-focus/30" @input="change"/></label></template>
<script setup lang="ts">import { ref, watch } from 'vue';import Icon from './Icon.vue';const props=withDefaults(defineProps<{modelValue:string;label?:string;placeholder?:string;delay?:number}>(),{label:'Search',placeholder:'Search…',delay:300});const emit=defineEmits<{ 'update:modelValue':[value:string] }>();const draft=ref(props.modelValue);let timer:ReturnType<typeof setTimeout>;watch(()=>props.modelValue,value=>{draft.value=value});function change(event:Event){draft.value=(event.target as HTMLInputElement).value;clearTimeout(timer);timer=setTimeout(()=>emit('update:modelValue',draft.value),props.delay)}</script>
